23
24    void printBoard() {
25
26        System.out.println(" " + board.get(0) + " | " + board.get(1) + " | " + board.get(2));
27        System.out.println("-----------");
28        System.out.println(" " + board.get(3) + " | " + board.get(4) + " | " + board.get(5));
29        System.out.println("-----------");
30        System.out.println(" " + board.get(6) + " | " + board.get(7) + " | " + board.get(8));
31
32    }
33
34    boolean updateBoard(int position, String type) {
35
36        boolean returnValue = false;
37
38        try {
39            // if a player selects position n, n-1 index should be updated
40            // if the position is not already filled, update the board
41            if (board.get(position - 1) == (" ")) {
42                board.set(position - 1, type);
43                // increase the value of count by 1
44                count = count + 1;
45
46                returnValue = true;
47            }
48
49            // if the position is already filled, ask user to select another position
50            else {
51                System.out.println("Position already selected. Select another position.");
52                returnValue = false;
53            }
54
55        }
56        catch (Exception e) {
57            System.out.println("Invalid position! Select another position.");
58        }
59        return returnValue;
60    }
61
62
63    // if all fields are selected and there is no winner, it's draw
64    // returning true if it's draw
65    boolean checkDraw() {
66
67        // check if count == 9
68        if (count == 9) {
69            return true;
70        }
71        else {
72            return false;
73        }
74    }
75
76    // if three symbols appears in a row, returning true
77    boolean checkWinner(String type) {
78        if ((board.get(0).equals(type) && board.get(1).equals(type) && board.get(2).equals(type))
79                || (board.get(3).equals(type) && board.get(4).equals(type) && board.get(5).equals(type))
80                || (board.get(6).equals(type) && board.get(7).equals(type) && board.get(8).equals(type))
81                || (board.get(0).equals(type) && board.get(3).equals(type) && board.get(6).equals(type))
82                || (board.get(1).equals(type) && board.get(4).equals(type) && board.get(7).equals(type))
83                || (board.get(2).equals(type) && board.get(5).equals(type) && board.get(8).equals(type))
84                || (board.get(0).equals(type) && board.get(4).equals(type) && board.get(8).equals(type))
85                || (board.get(2).equals(type) && board.get(4).equals(type) && board.get(6).equals(type))) {
86            return true;
87        }
88
89        else {
90            return false;
91        }
92
93    }
