118class Game {
119
120    Board b1 = new Board();
121
122    Player player1 = new Player("X");
123    Player player2 = new Player("O");
124    Player currentPlayer = player1;
125
126    // this method will be later used to play the game
127    void play() {
128
129        b1.addElements();
130        // using an infinite loop to run the game
131        // we will later add conditions to terminate the loop
132        String message = "enter the position (1 - 9):";
133
134        while (true) {
135            try {
136                message = "enter the position (1 - 9):";
137                System.out.println(currentPlayer.name + " " + message);
138                Scanner input = new Scanner(System.in);
139                int position = input.nextInt();
140
141                // the updateBoard() method return true if
142                // the user selected position is not already filled
143                if (b1.updateBoard(position, currentPlayer.type)) {
144
145                    b1.printBoard();
146
147                    // checking winner each time after updating the board
148                    if (b1.checkWinner(currentPlayer.type)) {
149                        System.out.println(currentPlayer.name + " wins!");
150                        break;
151                    }
152
153                    // checking draw each time after updating the board
154                    else if (b1.checkDraw()) {
155                        System.out.println("Game is a draw!");
156                        break;
157                    }
158
159                    // changing current player when board is updated
160                    else {
161                        if (currentPlayer == (player1)) {
162                            currentPlayer = player2;
163                        }
164
165                        else {
166                            currentPlayer = player1;
167
168                        }
169                    }
170
171                }
172
173            }
174            catch (Exception e) {
175                System.out.println("Invalid input! Enter a number between 1 and 9.");
176            }
177        }
178
179    }
180}
